  #pragma unroll
  for (int cc = 0; cc < OcPerBlock; ++cc) {
    int oc = oc_base + cc;
    if (oc >= OC) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      int od = od_arr[i];
      int oh = oh_arr[i];
      int ow = ow_arr[i];
      mY(oc, od, oh, ow) = static_cast<T>(acc[cc][i]);
    }
  }
}

